param([string]$ProjectRoot=(Split-Path -Parent $PSScriptRoot))
$ErrorActionPreference='Stop'
if([Threading.Thread]::CurrentThread.ApartmentState-ne[Threading.ApartmentState]::STA){throw 'Run with powershell.exe -STA.'}
$halcon='C:\Program Files\MVTec\HALCON-20.11-Progress';$env:PATH=(Join-Path $halcon 'bin\x64-win64')+';'+$env:PATH
Add-Type -AssemblyName PresentationFramework;Add-Type -AssemblyName System.Runtime.Serialization
$exe=Join-Path $ProjectRoot 'bin\x64\Debug\HalconWinFormsDemo.exe';$assembly=[Reflection.Assembly]::LoadFrom($exe)
function Assert([bool]$condition,[string]$message){if(-not$condition){throw $message}}
function Pump([int]$ms){$frame=New-Object Windows.Threading.DispatcherFrame;$timer=New-Object Windows.Threading.DispatcherTimer;$timer.Interval=[TimeSpan]::FromMilliseconds($ms);$timer.Add_Tick({$timer.Stop();$frame.Continue=$false});$timer.Start();[Windows.Threading.Dispatcher]::PushFrame($frame)}
function SyntheticImage(){[HalconDotNet.HObject]$base=$null;[HalconDotNet.HObject]$a1=$null;[HalconDotNet.HObject]$a2=$null;[HalconDotNet.HObject]$b1=$null;[HalconDotNet.HObject]$b2=$null;[HalconDotNet.HObject]$ua=$null;[HalconDotNet.HObject]$ub=$null;[HalconDotNet.HObject]$all=$null;[HalconDotNet.HObject]$painted=$null;try{[HalconDotNet.HOperatorSet]::GenImageConst([ref]$base,'byte',320,240);[HalconDotNet.HOperatorSet]::GenRectangle1([ref]$a1,40,45,75,54);[HalconDotNet.HOperatorSet]::GenRectangle1([ref]$a2,66,45,75,85);[HalconDotNet.HOperatorSet]::GenRectangle1([ref]$b1,135,190,180,201);[HalconDotNet.HOperatorSet]::GenRectangle1([ref]$b2,169,190,180,242);[HalconDotNet.HOperatorSet]::Union2($a1,$a2,[ref]$ua);[HalconDotNet.HOperatorSet]::Union2($b1,$b2,[ref]$ub);[HalconDotNet.HOperatorSet]::Union2($ua,$ub,[ref]$all);[HalconDotNet.HOperatorSet]::PaintRegion($all,$base,[ref]$painted,255,'fill');New-Object HalconDotNet.HImage($painted)}finally{foreach($o in @($base,$a1,$a2,$b1,$b2,$ua,$ub,$all,$painted)){if($null-ne$o){$o.Dispose()}}}}
$main=$assembly.GetType('HalconWinFormsDemo.MainWindow',$true);$serviceType=$assembly.GetType('HalconWinFormsDemo.Services.RecipeService',$true);$loggerType=$assembly.GetType('HalconWinFormsDemo.Services.AppLogger',$true);$kindType=$assembly.GetType('HalconWinFormsDemo.Models.VmToolKind',$true);$roiType=$assembly.GetType('HalconWinFormsDemo.Models.RoiData',$true);$templateType=$assembly.GetType('HalconWinFormsDemo.Models.TemplateDefinition',$true);$optionsType=$assembly.GetType('HalconWinFormsDemo.Models.TemplateMatchOptions',$true);$shapeServiceType=$assembly.GetType('HalconWinFormsDemo.Services.ShapeTemplateService',$true);$metadataType=$assembly.GetType('HalconWinFormsDemo.Models.ToolMetadata',$true);$recipeType=$assembly.GetType('HalconWinFormsDemo.Models.VisionRecipe',$true)
$private=[Reflection.BindingFlags]'Instance,NonPublic';$allFlags=[Reflection.BindingFlags]'Instance,NonPublic,Public';$static=[Reflection.BindingFlags]'Static,Public';$temp=Join-Path([IO.Path]::GetTempPath())('halcon-vm-s63-'+[Guid]::NewGuid().ToString('N'));[IO.Directory]::CreateDirectory($temp)|Out-Null
$service=$serviceType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$logger=$loggerType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$window=$main.GetConstructor($private,$null,[Type[]]@($serviceType,$loggerType),$null).Invoke([object[]]@($service,$logger))
$app=[Windows.Application]::Current;$ownsApp=$null-eq$app;if($ownsApp){$app=New-Object Windows.Application;$app.ShutdownMode=[Windows.ShutdownMode]::OnExplicitShutdown};$window.ShowInTaskbar=$false;$window.Left=-10000;$window.Show();Pump 180
function F([string]$name){$field=$main.GetField($name,$allFlags);$value=$field.GetValue($window);Write-Output -NoEnumerate $value}
function M([string]$name,[object[]]$parameters=@()){try{$main.GetMethod($name,$private).Invoke($window,$parameters)}catch{$e=$_.Exception;while($e.InnerException){$e=$e.InnerException};throw($name+': '+$e.Message)}}
function Kind([string]$name){[Enum]::Parse($kindType,$name)}
function Tool([string]$kind,[string]$name){M 'CreateFlowTool' ([object[]]@((Kind $kind),$name,$true,$null))}
function Out($tool,[string]$name){$args=[object[]]@($name,$null);Assert($tool.GetType().GetMethod('TryGetOutputValue').Invoke($tool,$args))('Missing output '+$name);$args[1]}
$image=SyntheticImage
try{
  # A: Shape is now a normal dock task, not a compatibility popup, while the complete catalog remains available.
  Assert((F 'toolCatalog').Count -eq [Enum]::GetValues($kindType).Count) 'S63 regressed the full toolbox';Assert((F 'toolCatalogMode')-eq'All') 'S63 changed the full-catalog default';Assert((F 'DockShapeMatchPanel')-ne$null) 'Shape task panel is missing';Assert((F 'DockShapeCandidatesDataGrid')-ne$null) 'Shape candidate table is missing';
  $shapeKind=Kind ShapeMatch;$outputs=$metadataType.GetMethod('GetOutputPorts',$static).Invoke($null,[object[]]@($shapeKind));foreach($port in @('XLD','Score','MatchCount','Row','Column','Angle','Scale','Candidates','ResultCode')){Assert(($outputs|Where-Object{$_.PortName-eq$port}).Count-eq1)('Shape output missing: '+$port)}

  # Train a real scaled HALCON shape model from the first L target and persist the managed resource.
  $trainRoi=$roiType.GetMethod('CreateRectangle',$static).Invoke($null,[object[]]@([double]34,[double]38,[double]82,[double]92));$options=[Activator]::CreateInstance($optionsType);$options.MinScore=.45;$options.MaxMatches=4;$options.AngleStartDeg=-10;$options.AngleExtentDeg=20;$options.ScaleMin=.75;$options.ScaleMax=1.55;$options.MaxOverlap=.25;$options.Greediness=.8;$options.LimitToSearchRoi=$true;$definition=[Activator]::CreateInstance($templateType);$definition.TemplateName='S63 L Model';$definition.TemplateRoi=$trainRoi.Clone();$definition.TrainingMask=$templateType.GetMethod('CloneRegion',$static).Invoke($null,[object[]]@($trainRoi.Region));$definition.DisplayFrame=$trainRoi.Clone();$definition.Options=$options;$shapeService=[Activator]::CreateInstance($shapeServiceType);$modelPath=Join-Path $temp 's63-l-model.shm';try{$shapeService.Train($image,$definition);$shapeService.Save($modelPath);Assert((Test-Path $modelPath)) 'Managed .shm was not written';$search=$roiType.GetMethod('CreateRectangle',$static).Invoke($null,[object[]]@([double]0,[double]0,[double]239,[double]319));try{$matches=$shapeService.Match($image,$search.Region,$options);Assert($matches.Count-ge2) 'Real HALCON scaled multi-target search did not find both L targets';Assert($matches[0].Index-eq1-and$matches[1].Index-eq2) 'Candidates are not stably indexed';Assert($matches[0].Score-ge$matches[1].Score) 'Candidates are not score ordered';Assert(($matches|Where-Object{$_.Scale-gt1.1}).Count-ge1) 'Scaled target did not produce a scale pose'}finally{$search.Dispose()}}finally{$shapeService.Dispose();$definition.Dispose();$trainRoi.Dispose()}

  # Run through the real flow tool, managed XLD layer, candidate summary and PositionCorrection2D chain.
  $main.GetField('currentImage',$private).SetValue($window,$image);$main.GetField('currentImagePath',$private).SetValue($window,'S63 synthetic L targets');(F 'viewport').SetImageSize(320,240)
  $flow=F 'flowTools';M 'DisposeAllShapeToolResources'|Out-Null;M 'DisposeFlowTools'|Out-Null;$flow.Clear();$shape=Tool ShapeMatch 'Multi Shape Locator';$correction=Tool PositionCorrection2D 'Pose Correction';$flow.Add($shape);$flow.Add($correction)
  $trainingGeometry=$roiType.GetMethod('CreateRectangle',$static).Invoke($null,[object[]]@([double]34,[double]38,[double]82,[double]92));$training=M 'AddRoiLayer' ([object[]]@($trainingGeometry,'Shape Training',$null));$trainingGeometry.Dispose();$searchGeometry=$roiType.GetMethod('CreateRectangle',$static).Invoke($null,[object[]]@([double]0,[double]0,[double]239,[double]319));$searchLayer=M 'AddRoiLayer' ([object[]]@($searchGeometry,'Shape Search',$shape));$searchGeometry.Dispose()
  $shape.Parameters.ShapeModelPath=$modelPath;$shape.Parameters.ShapeModelName='S63 L Model';$shape.Parameters.ShapeTrainingRoiId=$training.RoiId;$shape.Parameters.ShapeMinScore=.45;$shape.Parameters.ShapeMaxMatches=4;$shape.Parameters.ShapeAngleStartDegrees=-10;$shape.Parameters.ShapeAngleExtentDegrees=20;$shape.Parameters.ShapeScaleMin=.75;$shape.Parameters.ShapeScaleMax=1.55;$shape.Parameters.ShapeMaxOverlap=.25;$shape.Parameters.ShapeGreediness=.8
  $record=M 'ExecuteFlowTool' ([object[]]@($shape,'S63 flow'));Assert($record.ResultCode-eq'OK') 'Shape flow execution failed';Assert([double](Out $shape MatchCount)-ge2) 'Shape flow did not publish multi-target MatchCount';Assert((Out $shape Candidates)-match'#1.*Scale') 'Candidate summary was not published';Assert((Out $shape XLD).ObjectCount-ge2) 'Managed candidate XLD was not published'
  $correction.SetInputBinding('CurrentRow',$shape.ToolId,'Row');$correction.SetInputBinding('CurrentColumn',$shape.ToolId,'Column');$correction.SetInputBinding('CurrentAngle',$shape.ToolId,'Angle');$correction.Parameters.PositionCorrectionReferenceRow=[double](Out $shape Row);$correction.Parameters.PositionCorrectionReferenceColumn=[double](Out $shape Column);$correction.Parameters.PositionCorrectionReferenceAngleDegrees=[double](Out $shape Angle);Assert((M 'ExecuteFlowTool' ([object[]]@($correction,'S63 pose chain'))).ResultCode-eq'OK') 'Shape best pose did not drive PositionCorrection2D';Assert([Math]::Abs([double](Out $correction DeltaRow))-lt1e-9-and[Math]::Abs([double](Out $correction DeltaColumn))-lt1e-9) 'Shape pose chain values changed'

  # Dock visibility, candidates, recipe JSON and missing/no-match diagnostics clear stale poses.
  (F 'FlowToolList').SelectedItem=$shape;M 'LoadDockConfigurationDraft' ([object[]]@($shape))|Out-Null;Assert((F 'DockShapeMatchPanel').Visibility.ToString()-eq'Visible') 'Selected Shape did not open the unified task';Assert((F 'DockCompatibilityPanel').Visibility.ToString()-eq'Collapsed') 'Shape still exposes compatibility popup as normal path';M 'RefreshDockConfigurationRuntime' ([object[]]@($shape))|Out-Null;Assert((F 'DockShapeCandidatesDataGrid').Items.Count-ge2) 'Candidate table was not populated'
  $captured=M 'CaptureRecipe';$serializer=[Runtime.Serialization.Json.DataContractJsonSerializer]::new($recipeType);$stream=New-Object IO.MemoryStream;try{$serializer.WriteObject($stream,$captured);$stream.Position=0;$roundtrip=$serializer.ReadObject($stream)}finally{$stream.Dispose()};$saved=$roundtrip.ToolFlow|Where-Object{$_.ToolId-eq$shape.ToolId}|Select-Object -First 1;Assert($saved.Parameters.ShapeModelPath-eq$modelPath-and$saved.Parameters.ShapeScaleMax-eq1.55) 'Recipe lost Shape resource/scale parameters'
  $shape.Parameters.ShapeMinScore=.9999;M 'ExecuteFlowTool' ([object[]]@($shape,'S63 no match'))|Out-Null;Assert($shape.ResultCode-eq'NG'-and[double](Out $shape MatchCount)-eq0) 'No-match boundary was not NG';Assert($null-eq(Out $shape Row)-and(Out $shape Candidates)-eq'[]') 'No-match did not clear stale pose/candidates'
  $shape.Parameters.ShapeMinScore=.45;$shape.Parameters.ShapeModelPath=Join-Path $temp 'missing.shm';M 'DisposeShapeToolResource' ([object[]]@($shape.ToolId))|Out-Null;$failed=$false;$failureMessage='';try{M 'ExecuteFlowTool' ([object[]]@($shape,'S63 stale resource'))|Out-Null}catch{$failed=$true;$failureMessage=$_.Exception.Message};Assert($failed) 'Missing Shape resource was accepted';Assert($failureMessage-match'Shape|模型|过期|丢失')('Missing resource diagnostic is unclear: '+$failureMessage)
  Write-Output 'S63 VM-style Shape dock task + HALCON scaled multi-target pose + candidate XLD/table + PositionCorrection2D chain + recipe/no-match/stale-resource passed; BSB not implemented by user directive.'
}finally{$main.GetField('currentImage',$private).SetValue($window,$null);$image.Dispose();$main.GetField('recipeCloseConfirmed',$private).SetValue($window,$true);$window.Close();if($ownsApp){$app.Shutdown()};if(Test-Path $temp){Remove-Item -LiteralPath $temp -Recurse -Force}}
